export const GHOSTDROP_HTML = "<!doctype html>\n<html>\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover\">\n<title>Ghost Drop</title>\n<style>\nhtml,body{margin:0;height:100%;overflow:hidden;background:#140f33;touch-action:none;font-family:ui-rounded,\"SF Pro Rounded\",\"Nunito\",\"Fredoka\",system-ui,-apple-system,\"Segoe UI\",Roboto,sans-serif;color:#fff;user-select:none;-webkit-user-select:none}\ncanvas{display:block}\n.hud{position:fixed;pointer-events:none;font-weight:700}\n.pill{background:rgba(28,21,69,.55);border:1px solid rgba(255,255,255,.18);border-radius:16px;backdrop-filter:blur(10px);-webkit-backdrop-filter:blur(10px);box-shadow:0 6px 22px rgba(10,4,40,.35)}\n#left{left:14px;top:calc(12px + env(safe-area-inset-top));padding:8px 14px 9px;font-size:12px;letter-spacing:.06em;text-transform:uppercase;color:rgba(255,255,255,.78)}\n#count{display:block;font-size:32px;line-height:1.05;font-weight:800;color:#fff;letter-spacing:0;text-transform:none}\n#layer{left:14px;top:calc(84px + env(safe-area-inset-top));padding:7px 12px;font-size:14px;display:flex;align-items:center;gap:8px}\n#swatch{display:inline-block;width:12px;height:12px;border-radius:50%;background:#a58bff;box-shadow:0 0 10px currentColor}\n#big{left:0;right:0;top:30%;text-align:center;font-size:104px;font-weight:900;letter-spacing:2px;opacity:0;transform:scale(.6);transition:opacity .2s,transform .25s;background:linear-gradient(180deg,#fff,#ffc4ea 55%,#b9a2ff);-webkit-background-clip:text;background-clip:text;color:transparent;filter:drop-shadow(0 4px 18px rgba(255,79,216,.55))}\n#big.on{opacity:1;transform:scale(1)}\n#hint{left:50%;transform:translateX(-50%);bottom:calc(16px + env(safe-area-inset-bottom));text-align:center;font-size:13px;padding:7px 14px;white-space:nowrap;color:rgba(255,255,255,.9)}\n#hint:empty{display:none}\n.panel{position:fixed;left:50%;top:50%;transform:translate(-50%,-50%);width:min(340px,86vw);text-align:center;background:rgba(28,21,69,.72);backdrop-filter:blur(14px);-webkit-backdrop-filter:blur(14px);border:1px solid rgba(255,255,255,.2);border-radius:24px;padding:22px 20px;box-shadow:0 14px 44px rgba(10,4,40,.5)}\n.panel h1{margin:0 0 6px;font-size:34px;font-weight:800;text-shadow:0 0 18px rgba(255,79,216,.55)}\n.panel p{margin:6px 0;opacity:.92;line-height:1.35}\n.panel button{margin-top:14px;font:inherit;font-weight:700;font-size:18px;min-height:48px;padding:12px 22px;border-radius:16px;border:0;background:linear-gradient(160deg,#7c4dff,#ff4fd8);color:#fff;cursor:pointer;min-width:200px;box-shadow:0 6px 20px rgba(255,79,216,.35)}\n.panel button:focus-visible{outline:3px solid #fff;outline-offset:3px}\n.panel button:disabled{opacity:.45;cursor:default}\n.panel button[hidden]{display:none}\n#roster{display:flex;flex-wrap:wrap;gap:6px;justify-content:center;margin-top:10px}\n#roster span{font-size:13px;padding:4px 10px;border-radius:999px;background:rgba(255,255,255,.12)}\n.hidden{display:none !important}\n</style>\n</head>\n<body>\n<!-- Ghost Drop: 4 stacked hex layers (up to 10), far enough apart for the camera to sit between them. Tiles light up under a ghost and vanish a moment later;\n     a ghost that falls past the bottom layer is out. Last ghost standing wins.\n     Edit the numbers in the config block below. The Möbius Worlds server reads the same block\n     (python3 tools/bundle_ghostdrop.py copies it), so change it here and re-bundle. -->\n<script type=\"application/json\" id=\"ghostdrop-config\">\n{\n  \"layers\": 4,\n  \"tileRadius\": 3,\n  \"tileSize\": 1.1,\n  \"layerGap\": 9,\n  \"layerColors\": [\"#a58bff\", \"#ff8cc6\", \"#5fe0cf\", \"#ffd36b\"],\n  \"tileDelayMs\": 800,\n  \"minPlayers\": 2,\n  \"maxPlayers\": 8,\n  \"countdownMs\": 3000,\n  \"finishGraceMs\": 1500,\n  \"winnerMs\": 7000,\n  \"ghostHeight\": 1.2,\n  \"moveSpeed\": 5.6,\n  \"jumpSpeed\": 7.2,\n  \"gravity\": 13,\n  \"fallSpeed\": 16,\n  \"floatGravity\": 4,\n  \"floatMs\": 320,\n  \"diveSpeed\": 12,\n  \"diveMs\": 220,\n  \"diveCooldownMs\": 1400\n}\n</script>\n\n<div id=\"left\" class=\"hud pill\"><span id=\"countLabel\">Players left</span><span id=\"count\">-</span></div>\n<div id=\"layer\" class=\"hud pill\"><i id=\"swatch\"></i><span id=\"layerText\"></span></div>\n<div id=\"big\" class=\"hud\"></div>\n<div id=\"hint\" class=\"hud pill\"></div>\n<div id=\"panel\" class=\"panel hidden\">\n  <h1 id=\"ptitle\"></h1>\n  <p id=\"pbody\"></p>\n  <div id=\"roster\"></div>\n  <button id=\"pbtn\" type=\"button\" hidden></button>\n</div>\n\n<script type=\"module\">\nimport * as THREE from 'https://esm.sh/three@0.180.0';\nimport { GLTFLoader } from 'https://esm.sh/three@0.180.0/examples/jsm/loaders/GLTFLoader.js';\nimport { RoomEnvironment } from 'https://esm.sh/three@0.180.0/examples/jsm/environments/RoomEnvironment.js';\n\n// ---------- config and setup ----------\nconst CONFIG = JSON.parse(document.getElementById('ghostdrop-config').textContent);\nconst LAYERS = Math.max(1, Math.min(10, CONFIG.layers));\nconst RINGS = Math.max(2, CONFIG.tileRadius);          // hex rings out from the middle\nconst TS = CONFIG.tileSize, SQ3 = Math.sqrt(3), TILE_H = 0.5;\nconst layerY = (L) => -L * CONFIG.layerGap;             // the top layer is y = 0\nconst VOID_Y = layerY(LAYERS - 1) - 3;                  // below this, a ghost is out\n// Stays false (a solo practice drop) until Worlds sends its first live round, which sets it true.\nlet LIVE = false;\nconst studio = window.studio || { input: { x: 0, y: 0, a: false, b: false }, model: () => null, controls() {}, sound() {}, save() {}, load: () => undefined };\nconst send = (message) => { if (LIVE) parent.postMessage(message, '*'); };\nlet clockOffset = 0;                                    // server time minus this device's time\nconst serverNow = () => Date.now() + clockOffset;\n\nconst SFX = {\n  step: [0.35, 0, 660, 0, 0.03, 0.07, 0, 1.2, 30],\n  vanish: [0.25, 0, 1200, 0, 0.12, 0.2, 3, 0.3, -80],\n  fall: [0.45, 0, 380, 0.04, 0.3, 0.6, 1, 0.5, -40],\n  out: [0.6, 0, 260, 0.02, 0.45, 0.7, 3, 0.2, -30],\n  win: [0.6, 0, 523, 0.02, 0.25, 0.5, 0, 1.4],\n  tick: [0.3, 0, 880, 0, 0.05, 0.05],\n  go: [0.5, 0, 1040, 0, 0.25, 0.3, 0, 1.6],\n};\nconst sfx = (name) => { try { studio.sound?.(name, SFX[name]); } catch (e) { /* no audio: the game plays on */ } };\n\n// ---------- the Worlds ghost (the same model and outfits as Möbius Worlds) ----------\nconst PIECES = ['face_dots', 'face_happy', 'face_mystery', 'face_sleepy', 'face_starry', 'ghost', 'hat_beanie', 'hat_crown',\n  'hat_headphones', 'hat_mobius_cap', 'hat_mobius_halo', 'hat_party', 'hold_balloon', 'hold_mobius_mug', 'hold_pencil',\n  'hold_tote', 'neck_bowtie', 'neck_lanyard', 'neck_mobius_scarf'];\nconst lib = {};\nlet ghostK = 1, ghostLift = 0;\nasync function loadGhosts() {\n  const loader = new GLTFLoader();\n  await Promise.all(PIECES.filter((n) => studio.model?.('wg_' + n)).map((n) => new Promise((done) => {\n    loader.parse(studio.model('wg_' + n), '', (g) => {\n      // some pieces ship without normals; lit materials need them or they render black (as in the lobby)\n      g.scene.traverse((o) => { if (o.isMesh && o.geometry && !o.geometry.attributes.normal) o.geometry.computeVertexNormals(); });\n      lib[n] = g.scene; done();\n    }, () => done());\n  })));\n  if (lib.ghost) {\n    const box = new THREE.Box3().setFromObject(lib.ghost);\n    const h = (box.max.y - box.min.y) || 1;\n    ghostK = CONFIG.ghostHeight / h;\n    ghostLift = -box.min.y * ghostK;                    // stand the ghost on its feet\n  }\n}\n\n// ---------- scene: the Möbius Worlds night (the lobby's sky, light and glossy toy look) ----------\nconst SKY = '#140f33', FOG = '#1c1545';\nconst scene = new THREE.Scene();\nscene.background = new THREE.Color(SKY);\nscene.fog = new THREE.Fog(FOG, 34, 150);\nconst renderer = new THREE.WebGLRenderer({ antialias: true });\nrenderer.setPixelRatio(Math.min(devicePixelRatio, 2));\nrenderer.setSize(innerWidth, innerHeight);\nrenderer.outputColorSpace = THREE.SRGBColorSpace;\nrenderer.toneMapping = THREE.ACESFilmicToneMapping;\nrenderer.toneMappingExposure = 1.05;\nrenderer.domElement.style.cssText = 'display:block;width:100vw;height:100vh;touch-action:none;filter:saturate(1.25) contrast(1.08)';\ndocument.body.prepend(renderer.domElement);\nconst camera = new THREE.PerspectiveCamera(52, innerWidth / innerHeight, 0.1, 600);\ncamera.position.set(0, 6, 12);\nfunction fitCamera() {\n  camera.aspect = innerWidth / innerHeight;\n  camera.fov = camera.aspect < 0.8 ? 62 : 52;            // a phone held upright gets a wider view\n  camera.updateProjectionMatrix();\n}\nfitCamera();\naddEventListener('resize', () => { renderer.setSize(innerWidth, innerHeight); fitCamera(); });\n// The lobby's light: lilac sky light, a soft violet sun and a cool rim from behind.\nscene.add(new THREE.HemisphereLight('#8f86ff', '#2a1f4a', 1.5));\nscene.add(new THREE.AmbientLight('#ffffff', 0.35));\nconst sun = new THREE.DirectionalLight('#d9d3ff', 2.0);\nsun.position.set(8, 30, 14);\nscene.add(sun);\nconst rim = new THREE.DirectionalLight('#bfd8ff', 1.4);\nrim.position.set(-20, 12, -30);\nscene.add(rim);\nconst toyEnv = (() => { const pm = new THREE.PMREMGenerator(renderer); const t = pm.fromScene(new RoomEnvironment(), 0.04).texture; pm.dispose(); return t; })();\n// Glossy, clear-coated plastic, as in the lobby's toy style.\nfunction toy(color, opts = {}) {\n  return new THREE.MeshPhysicalMaterial({ color, roughness: 0.4, metalness: 0, clearcoat: 1, clearcoatRoughness: 0.14,\n    envMap: toyEnv, envMapIntensity: 0.45, ...opts });\n}\nfunction softDot(inner, outer) {                          // a round soft glow texture\n  const c = document.createElement('canvas');\n  c.width = c.height = 128;\n  const g = c.getContext('2d'), grad = g.createRadialGradient(64, 64, 0, 64, 64, 64);\n  grad.addColorStop(0, inner);\n  grad.addColorStop(1, outer);\n  g.fillStyle = grad;\n  g.fillRect(0, 0, 128, 128);\n  const t = new THREE.CanvasTexture(c);\n  t.colorSpace = THREE.SRGBColorSpace;\n  return t;\n}\nconst GLOW = softDot('rgba(255,255,255,1)', 'rgba(255,255,255,0)');\n{ // sky dome: deep indigo overhead, warm violet toward the horizon\n  const geo = new THREE.SphereGeometry(400, 32, 16);\n  const mat = new THREE.ShaderMaterial({ side: THREE.BackSide, depthWrite: false, fog: false,\n    uniforms: { top: { value: new THREE.Color('#120c30') }, mid: { value: new THREE.Color('#2b1d63') }, low: { value: new THREE.Color('#4a2a86') } },\n    vertexShader: 'varying vec3 vP; void main(){ vP = normalize(position); gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.0); }',\n    fragmentShader: 'uniform vec3 top, mid, low; varying vec3 vP; void main(){ float h = vP.y; vec3 c = h > 0.0 ? mix(mid, top, smoothstep(0.0, 0.7, h)) : mix(mid, low, smoothstep(0.0, -0.5, h)); gl_FragColor = vec4(c, 1.0); \\n#include <tonemapping_fragment>\\n#include <colorspace_fragment>\\n}' });\n  const dome = new THREE.Mesh(geo, mat);\n  dome.renderOrder = -1;\n  scene.add(dome);\n}\n{ // stars, twinkling in two sizes\n  for (const [n, size, op] of [[260, 0.9, 0.85], [90, 1.8, 0.95]]) {\n    const pos = new Float32Array(n * 3);\n    for (let i = 0; i < n; i++) {\n      const a = Math.random() * Math.PI * 2, e = 0.08 + Math.random() * 1.3, r = 300;\n      pos.set([Math.cos(a) * Math.cos(e) * r, Math.sin(e) * r - 40, Math.sin(a) * Math.cos(e) * r], i * 3);\n    }\n    const geo = new THREE.BufferGeometry();\n    geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));\n    scene.add(new THREE.Points(geo, new THREE.PointsMaterial({ color: '#fff6ff', size, map: GLOW, transparent: true, opacity: op, depthWrite: false, fog: false, sizeAttenuation: true })));\n  }\n}\n{ // the Möbius moon, with a halo\n  const moon = new THREE.Mesh(new THREE.SphereGeometry(22, 32, 20), new THREE.MeshBasicMaterial({ color: '#f3e9ff', fog: false }));\n  moon.position.set(-120, 95, -230);\n  const halo = new THREE.Sprite(new THREE.SpriteMaterial({ map: GLOW, color: '#c9a6ff', transparent: true, opacity: 0.55, depthWrite: false, fog: false }));\n  halo.scale.setScalar(130);\n  halo.position.copy(moon.position);\n  const band = new THREE.Mesh(new THREE.TorusGeometry(30, 1.6, 8, 64), new THREE.MeshBasicMaterial({ color: '#ff9ce0', fog: false, transparent: true, opacity: 0.8 }));\n  band.position.copy(moon.position); band.rotation.set(1.2, 0.3, 0.5);\n  scene.add(halo, moon, band);\n}\nconst islands = [];\n{ // little floating islands round the arena, like pieces of the lobby island drifting in the night\n  const rock = toy('#5a3fa8', { clearcoat: 0.3, roughness: 0.7 }), grass = [toy('#d9a8ff'), toy('#ffb3dc'), toy('#9fe8d9')];\n  const tree = toy('#ffd1f0', { emissive: '#ff8cc6', emissiveIntensity: 0.25 });\n  for (let i = 0; i < 9; i++) {\n    const a = (i / 9) * Math.PI * 2 + Math.random() * 0.4, d = 48 + Math.random() * 40, size = 2.4 + Math.random() * 3;\n    const g = new THREE.Group();\n    const under = new THREE.Mesh(new THREE.ConeGeometry(size, size * 1.6, 7), rock);\n    under.rotation.x = Math.PI; under.position.y = -size * 0.8;\n    const top = new THREE.Mesh(new THREE.CylinderGeometry(size * 1.02, size * 0.98, size * 0.28, 7), grass[i % 3]);\n    g.add(under, top);\n    for (let k = 0; k < 1 + (i % 3); k++) {\n      const t = new THREE.Mesh(new THREE.IcosahedronGeometry(size * 0.32, 0), tree);\n      t.position.set((Math.random() - 0.5) * size, size * 0.45, (Math.random() - 0.5) * size);\n      g.add(t);\n    }\n    g.position.set(Math.cos(a) * d, 4 - Math.random() * 34, Math.sin(a) * d);\n    g.rotation.y = Math.random() * Math.PI;\n    g.userData.phase = Math.random() * Math.PI * 2;\n    g.userData.y = g.position.y;\n    islands.push(g);\n    scene.add(g);\n  }\n}\n// The void below the bottom layer: a pink-violet glow you fall into, like the lobby's sea glow.\nconst voidDisc = new THREE.Mesh(new THREE.CircleGeometry(90, 48), new THREE.MeshBasicMaterial({ map: softDot('rgba(255,120,220,0.9)', 'rgba(60,30,130,0)'), transparent: true, depthWrite: false }));\nvoidDisc.rotation.x = -Math.PI / 2;\nvoidDisc.position.y = VOID_Y - 2;\nscene.add(voidDisc);\nconst puffs = [];                                       // soft clouds drifting in the void below\nfor (let i = 0; i < 18; i++) {\n  const s = new THREE.Sprite(new THREE.SpriteMaterial({ map: GLOW, color: i % 3 ? '#8a6dff' : '#ff8cd8', transparent: true, opacity: 0.2, depthWrite: false }));\n  s.position.set((Math.random() - 0.5) * 90, VOID_Y + Math.random() * 6, (Math.random() - 0.5) * 90);\n  s.scale.setScalar(14 + Math.random() * 12);\n  puffs.push(s);\n  scene.add(s);\n}\n\n// ---------- hex grid (pointy-top, axial q and r) ----------\nconst hexCenter = (q, r) => ({ x: TS * (SQ3 * q + (SQ3 / 2) * r), z: TS * 1.5 * r });\nconst inArena = (q, r) => Math.max(Math.abs(q), Math.abs(r), Math.abs(q + r)) <= RINGS;\nfunction hexAt(x, z) {\n  const r0 = z / (1.5 * TS), q0 = (x / TS - (SQ3 / 2) * r0) / SQ3, y0 = -q0 - r0;\n  let q = Math.round(q0), r = Math.round(r0);\n  const y = Math.round(y0);\n  const dq = Math.abs(q - q0), dy = Math.abs(y - y0), dr = Math.abs(r - r0);\n  if (dq > dy && dq > dr) q = -y - r;\n  else if (dy <= dr) r = -q - y;\n  return inArena(q, r) ? { q, r } : null;\n}\nconst tileId = (L, q, r) => `${L}:${q}:${r}`;\n\n// The ring two steps out, sorted round the circle: where ghosts spawn, spread evenly.\nconst SPAWN_RING = [];\nfor (let q = -RINGS; q <= RINGS; q++) for (let r = -RINGS; r <= RINGS; r++) {\n  if (inArena(q, r) && Math.max(Math.abs(q), Math.abs(r), Math.abs(q + r)) === 2) {\n    const c = hexCenter(q, r);\n    SPAWN_RING.push({ q, r, x: c.x, z: c.z, a: Math.atan2(c.z, c.x) });\n  }\n}\nSPAWN_RING.sort((a, b) => a.a - b.a);\nconst spotAt = (i, n) => SPAWN_RING[Math.floor(i * SPAWN_RING.length / Math.max(1, n)) % SPAWN_RING.length];\n\n// ---------- tiles: built once, pooled, and reused every round ----------\n// Each tile is a glossy candy hex: the layer colour on top, a paler pastel side (the lobby paving's\n// pink mortar look), so the hexes read apart. Groups of CylinderGeometry: 0 side, 1 top, 2 bottom.\nconst tiles = new Map();                                // id -> { mesh, top, side, color, lit, gone, L }\nconst tileGeo = new THREE.CylinderGeometry(TS * 0.93, TS * 0.88, TILE_H, 6);\nconst WHITE = new THREE.Color('#ffffff'), LIT = new THREE.Color('#fff4fd');\nconst layerColor = (L) => new THREE.Color(CONFIG.layerColors[L % CONFIG.layerColors.length]);\nconst layerRims = [];\nfor (let L = 0; L < LAYERS; L++) {\n  const color = layerColor(L), pale = color.clone().lerp(WHITE, 0.55);\n  for (let q = -RINGS; q <= RINGS; q++) for (let r = -RINGS; r <= RINGS; r++) {\n    if (!inArena(q, r)) continue;\n    const c = hexCenter(q, r);\n    const top = toy(color, { emissive: color, emissiveIntensity: 0.14, transparent: true });\n    const side = toy(pale, { emissive: color, emissiveIntensity: 0.08, transparent: true, clearcoat: 0.5 });\n    const mesh = new THREE.Mesh(tileGeo, [side, top, side]);\n    mesh.position.set(c.x, layerY(L) - TILE_H / 2, c.z);\n    scene.add(mesh);\n    tiles.set(tileId(L, q, r), { mesh, top, side, color, lit: false, gone: false, L });\n  }\n  // A glowing rim round each layer, like the lobby's curb: you always see where a layer ends.\n  const rimRing = new THREE.Mesh(new THREE.TorusGeometry(TS * SQ3 * (RINGS + 0.62), 0.07, 8, 96),\n    new THREE.MeshBasicMaterial({ color: color.clone().lerp(WHITE, 0.25), transparent: true, opacity: 0.85 }));\n  rimRing.rotation.x = Math.PI / 2;\n  rimRing.position.y = layerY(L) - TILE_H * 0.5;\n  scene.add(rimRing);\n  layerRims.push(rimRing);\n}\n// Layers above where the camera is looking fade back, so they never hide your ghost.\nconst fadeOf = new Array(LAYERS).fill(1);\nfunction tileLook(t, opacity) {\n  t.top.opacity = t.side.opacity = opacity;\n  const solid = opacity > 0.98;\n  if (t.top.depthWrite !== solid) { t.top.depthWrite = t.side.depthWrite = solid; }\n}\n\n// ---------- the round: the shared state (Worlds) or a local practice drop ----------\nconst emptyRound = () => ({ id: '', state: 'lobby', startAt: 0, winner: null, racers: {}, order: [], tiles: {}, out: {}, pos: {} });\nlet drop = emptyRound();\nconst seenOut = new Set();\n\nconst me = {\n  pid: 'you',\n  x: 0, y: 0, z: 0, vx: 0, vy: 0, vz: 0,\n  layer: 0, ground: null, face: { x: 0, z: -1 },\n  floatMs: 0, dive: 0, diveCool: 0, holdA: false, out: false,\n  watching: false,   // in a Worlds drop you did not join: you watch the ghosts from the camera\n};\nlet spawnKey = '';\n\nfunction newWorld() {\n  for (const t of tiles.values()) {\n    t.mesh.visible = true; t.mesh.scale.set(1, 1, 1); tileLook(t, fadeOf[t.L]);\n    t.top.color.copy(t.color); t.top.emissive.copy(t.color); t.top.emissiveIntensity = 0.14;\n    t.lit = false; t.gone = false;\n  }\n  for (const a of actors.values()) { a.root.visible = true; a.root.scale.setScalar(1); a.dying = null; a.gone = false; }\n  seenOut.clear();\n  me.out = false; me.dive = 0; me.floatMs = 0; me.diveCool = 0; me.vx = me.vy = me.vz = 0;\n}\n\nfunction spawnMe() {\n  const i = Math.max(0, drop.order.indexOf(me.pid)), n = Math.max(1, drop.order.length);\n  const s = spotAt(i, n);\n  me.x = s.x; me.z = s.z; me.y = layerY(0); me.layer = 0;\n  me.ground = tileId(0, s.q, s.r);\n  me.vx = me.vy = me.vz = 0; me.face = { x: 0, z: -1 };\n  spawnKey = drop.order.join(',');\n}\n\n// The round is the host's shared state from Worlds: who is in it (order), each ghost's last\n// report (pos) and when it fell (out_at), and the tiles with their server-stamped times.\n// The roster gives each real player's outfit for their ghost.\nfunction applyRound(message) {\n  if (message.now) clockOffset = message.now - Date.now();\n  if (message.live && !LIVE) { LIVE = true; me.pid = message.you; }\n  const r = message.round;\n  const fresh = !r || r.id !== drop.id;\n  const prev = drop.state;\n  if (r) {\n    const outfits = Object.fromEntries((message.roster || []).map((p) => [p.pid, p]));\n    const order = r.order || [], shared = r.racers || {};\n    const racers = {}, pos = {}, out = {};\n    for (const pid of order) {\n      const s = shared[pid] || {};\n      racers[pid] = { ...(outfits[pid] || {}), name: s.name, color: s.color };\n      if (s.pos) pos[pid] = s.pos;\n      if (s.out_at != null) out[pid] = { at: s.out_at };\n    }\n    // the host's tiles, plus your own steps it hasn't heard about yet (so they don't flicker back)\n    const tiles = { ...(r.tiles || {}) };\n    if (!fresh) for (const [id, t] of Object.entries(drop.tiles)) if (!tiles[id] && t.by === me.pid && t.stepAt > serverNow() - 4000) tiles[id] = t;\n    drop = { id: r.id, state: r.state, startAt: r.startAt || 0, winner: r.winner ?? null,\n             racers, order: [...order], tiles, out, pos };\n    if (LIVE && out[me.pid] && !me.out) me.out = true;   // the host took us out (silent or left)\n  } else {\n    drop = emptyRound();\n  }\n  me.watching = LIVE && drop.state !== 'lobby' && !drop.order.includes(me.pid);\n  if (fresh) { newWorld(); spawnMe(); }\n  else if ((drop.state === 'lobby' || drop.state === 'countdown') && drop.order.join(',') !== spawnKey) spawnMe();\n  for (const pid of Object.keys(drop.out)) {\n    if (!seenOut.has(pid)) { seenOut.add(pid); if (pid !== me.pid) sfx('out'); }\n  }\n  if (drop.state === 'done' && prev !== 'done') {\n    if (drop.winner === me.pid) sfx('win');\n    // the winner screen stays up a moment, then the frame closes and the island is back\n    if (LIVE) setTimeout(() => send({ type: 'ghostdrop:close' }), CONFIG.winnerMs);\n  }\n}\n\nfunction startPractice() {\n  drop = emptyRound();\n  drop.id = 'practice-' + Date.now();\n  drop.racers = { [me.pid]: { name: 'You', color: '#ffffff' } };\n  drop.order = [me.pid];\n  drop.state = 'countdown';\n  drop.startAt = Date.now() + CONFIG.countdownMs;\n  newWorld();\n  spawnMe();\n}\n\n// ---------- the ghosts ----------\nfunction nameTag(text, color) {\n  const c = document.createElement('canvas');\n  c.width = 256; c.height = 64;\n  const g = c.getContext('2d');\n  // a rounded Worlds pill with a dot in the player's colour\n  g.font = '700 28px ui-rounded, system-ui, sans-serif';\n  const label = String(text).slice(0, 14), w = Math.min(248, g.measureText(label).width + 62), x0 = (256 - w) / 2;\n  g.fillStyle = 'rgba(28,21,69,.78)';\n  g.beginPath(); g.roundRect(x0, 8, w, 48, 24); g.fill();\n  g.strokeStyle = 'rgba(255,255,255,.28)'; g.lineWidth = 2; g.stroke();\n  g.fillStyle = color;\n  g.beginPath(); g.arc(x0 + 24, 32, 9, 0, Math.PI * 2); g.fill();\n  g.textAlign = 'left';\n  g.textBaseline = 'middle';\n  g.fillStyle = '#ffffff';\n  g.fillText(label, x0 + 42, 33);\n  const tex = new THREE.CanvasTexture(c);\n  tex.colorSpace = THREE.SRGBColorSpace;\n  const sprite = new THREE.Sprite(new THREE.SpriteMaterial({ map: tex, transparent: true, depthWrite: false }));\n  sprite.scale.set(1.8, 0.45, 1);\n  sprite.position.y = CONFIG.ghostHeight + 0.35;\n  return sprite;\n}\n\nfunction makeGhost(color, profile) {\n  const root = new THREE.Group(), body = new THREE.Group();\n  root.add(body);\n  if (lib.ghost) {\n    const model = new THREE.Group();\n    model.scale.setScalar(ghostK);\n    model.position.y = ghostLift;\n    const shell = lib.ghost.clone(true);\n    shell.traverse((o) => {\n      if (o.isMesh && o.material?.name === 'Body') {\n        o.material = o.material.clone();\n        o.material.color.set(color);\n        o.material.emissive = new THREE.Color(color);\n        o.material.emissiveIntensity = 0.18;\n      }\n    });\n    model.add(shell);\n    for (const slot of ['face', 'hat', 'neck', 'hold']) {\n      const v = profile?.[slot] || (slot === 'face' ? 'dots' : 'none');\n      if (v !== 'none' && lib[`${slot}_${v}`]) model.add(lib[`${slot}_${v}`].clone(true));\n    }\n    // the lobby's toy look: every part glossy, clear-coated plastic\n    model.traverse((o) => {\n      if (!o.isMesh || !o.material) return;\n      const m = o.material;\n      o.material = toy(m.color, { emissive: m.emissive || new THREE.Color(0), emissiveIntensity: m.emissiveIntensity ?? 1,\n        map: m.map || null, emissiveMap: m.emissiveMap || null, roughness: 0.38 });\n      o.material.name = m.name || '';\n    });\n    body.add(model);\n  } else {\n    // standalone (or no Worlds models): a plain ghost shape in the same colour\n    const m = new THREE.MeshStandardMaterial({ color, emissive: color, emissiveIntensity: 0.25, roughness: 0.45, transparent: true, opacity: 0.92 });\n    const head = new THREE.Mesh(new THREE.SphereGeometry(0.42, 20, 14), m);\n    head.position.y = 0.85;\n    const skirt = new THREE.Mesh(new THREE.ConeGeometry(0.42, 0.6, 16, 1, true), m);\n    skirt.position.y = 0.3;\n    body.add(head, skirt);\n  }\n  return root;\n}\n\n// A soft shadow on the tile below each ghost (so you can judge a jump), and a glowing ring\n// in your colour under your own ghost, so you always spot yourself among the others.\nconst SHADOW = softDot('rgba(20,8,60,0.55)', 'rgba(20,8,60,0)');\nconst RING = (() => {\n  const c = document.createElement('canvas');\n  c.width = c.height = 128;\n  const g = c.getContext('2d');\n  g.strokeStyle = '#ffffff'; g.lineWidth = 9; g.shadowColor = '#ffffff'; g.shadowBlur = 10;\n  g.beginPath(); g.arc(64, 64, 50, 0, Math.PI * 2); g.stroke();\n  return new THREE.CanvasTexture(c);\n})();\nfunction floorDecal(map, color, size, opacity) {\n  const m = new THREE.Mesh(new THREE.PlaneGeometry(size, size), new THREE.MeshBasicMaterial({ map, color, transparent: true, opacity, depthWrite: false, fog: false }));\n  m.rotation.x = -Math.PI / 2;\n  m.renderOrder = 2;\n  scene.add(m);\n  return m;\n}\n// The top of the highest standing tile at or below height y under (x, z), or null over the void.\nfunction floorBelow(x, z, y, now) {\n  const hex = hexAt(x, z);\n  if (!hex) return null;\n  for (let L = 0; L < LAYERS; L++) {\n    if (layerY(L) > y + 0.05) continue;\n    if (supported(tileId(L, hex.q, hex.r), now)) return layerY(L);\n  }\n  return null;\n}\nfunction placeDecals(a, x, y, z, now) {\n  const floor = a.root.visible ? floorBelow(x, z, y, now) : null;\n  const show = floor !== null;\n  a.shadow.visible = show;\n  if (a.ring) a.ring.visible = show;\n  if (!show) return;\n  const k = Math.max(0.35, 1 - (y - floor) / 6);\n  a.shadow.position.set(x, floor + 0.02, z);\n  a.shadow.scale.setScalar(k);\n  if (a.ring) { a.ring.position.set(x, floor + 0.03, z); a.ring.scale.setScalar(0.85 + 0.08 * Math.sin(performance.now() / 260)); }\n}\nconst actors = new Map();                               // pid -> { root, dying, gone, shadow, ring }\nfunction actorFor(pid) {\n  let a = actors.get(pid);\n  if (!a) {\n    const p = drop.racers[pid] || {};\n    const root = makeGhost(p.color || '#d8d4ff', p);\n    if (pid !== me.pid) root.add(nameTag(p.name || 'Ghost', p.color || '#d8d4ff'));   // yours has the ring instead\n    scene.add(root);\n    a = { root, dying: null, gone: false, shadow: floorDecal(SHADOW, '#ffffff', 1.5, 1),\n          ring: pid === me.pid ? floorDecal(RING, p.color || '#ffffff', 1.55, 0.95) : null };\n    actors.set(pid, a);\n  }\n  return a;\n}\n\n// A wisp of light where a ghost is eliminated; the ghost shrinks away beside it.\nconst wisps = [];\nfunction wisp(x, y, z, color) {\n  const n = 28, pos = new Float32Array(n * 3), vel = new Float32Array(n * 3);\n  for (let i = 0; i < n; i++) {\n    pos.set([x + (Math.random() - 0.5) * 0.6, y + Math.random() * 0.4, z + (Math.random() - 0.5) * 0.6], i * 3);\n    vel.set([(Math.random() - 0.5) * 1.4, 0.9 + Math.random() * 1.6, (Math.random() - 0.5) * 1.4], i * 3);\n  }\n  const geo = new THREE.BufferGeometry();\n  geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));\n  const mat = new THREE.PointsMaterial({ color, size: 0.32, transparent: true, opacity: 1, depthWrite: false, blending: THREE.AdditiveBlending });\n  const points = new THREE.Points(geo, mat);\n  scene.add(points);\n  wisps.push({ points, geo, mat, pos, vel, life: 1.1 });\n}\nfunction updateWisps(dt) {\n  for (let i = wisps.length - 1; i >= 0; i--) {\n    const w = wisps[i];\n    w.life -= dt;\n    for (let j = 0; j < w.pos.length; j++) w.pos[j] += w.vel[j] * dt;\n    w.geo.attributes.position.needsUpdate = true;\n    w.mat.opacity = Math.max(0, w.life / 1.1);\n    if (w.life <= 0) { scene.remove(w.points); w.geo.dispose(); w.mat.dispose(); wisps.splice(i, 1); }\n  }\n}\nfunction startDying(a, x, y, z, color) {\n  a.dying = 0;\n  wisp(x, y + 0.6, z, color);\n}\nfunction tickDying(a, dt) {\n  if (a.dying === null) return;\n  a.dying += dt;\n  const k = Math.min(1, a.dying / 0.8);\n  a.root.scale.setScalar(Math.max(0.001, 1 - k));\n  if (k >= 1) { a.root.visible = false; a.gone = true; a.dying = null; }\n}\nconst colorOf = (pid) => drop.racers[pid]?.color || '#d8d4ff';\nconst nameOf = (pid) => drop.racers[pid]?.name || 'Ghost';\n\nfunction updateActors(dt) {\n  for (const pid of [...actors.keys()]) {\n    if (pid !== me.pid && !drop.order.includes(pid)) {\n      const a = actors.get(pid);\n      scene.remove(a.root, a.shadow);\n      if (a.ring) scene.remove(a.ring);\n      actors.delete(pid);\n    }\n  }\n  for (const pid of drop.order) {\n    if (pid === me.pid) continue;\n    const a = actorFor(pid);\n    const p = drop.pos[pid];\n    if (p) {\n      const k = 1 - Math.exp(-dt * 10);\n      a.root.position.x += (p.x - a.root.position.x) * k;\n      a.root.position.y += (p.y - a.root.position.y) * k;\n      a.root.position.z += (p.z - a.root.position.z) * k;\n      a.root.rotation.y = p.r || 0;\n    } else if (!a.placed) {\n      const s = spotAt(drop.order.indexOf(pid), drop.order.length);\n      a.root.position.set(s.x, layerY(0), s.z);\n      a.placed = true;\n    }\n    if (drop.out[pid] && !a.gone && a.dying === null) startDying(a, a.root.position.x, a.root.position.y, a.root.position.z, colorOf(pid));\n    tickDying(a, dt);\n    placeDecals(a, a.root.position.x, a.root.position.y, a.root.position.z, serverNow());\n  }\n  const mine = actorFor(me.pid);\n  mine.root.position.set(me.x, me.y, me.z);\n  mine.root.rotation.y = Math.atan2(me.face.x, me.face.z);\n  mine.root.visible = !me.watching;\n  if (me.out && !me.watching && !mine.gone && mine.dying === null) startDying(mine, me.x, me.y, me.z, colorOf(me.pid));\n  tickDying(mine, dt);\n  if (mine.ring) mine.ring.material.color.set(colorOf(me.pid));\n  placeDecals(mine, me.x, me.y, me.z, serverNow());\n}\n\n// ---------- your ghost: run, jump, float, dive, fall ----------\nfunction supported(id, now) {\n  if (!tiles.has(id)) return false;\n  const vanishAt = drop.tiles[id]?.vanishAt;\n  return !(vanishAt && now >= vanishAt);\n}\nfunction stepOn(id, now) {\n  if (drop.state !== 'running' || now < drop.startAt || drop.tiles[id]) return;\n  drop.tiles[id] = { stepAt: now, vanishAt: now + CONFIG.tileDelayMs, by: me.pid };\n  sfx('step');\n  send({ type: 'ghostdrop:step', tile: id, at: now });\n}\nfunction findLanding(from, to, now) {\n  const hex = hexAt(me.x, me.z);\n  if (!hex) return null;\n  for (let L = 0; L < LAYERS; L++) {\n    const top = layerY(L);\n    if (top > from + 1e-4) continue;                    // above where we were\n    if (top < to - 1e-4) break;                         // not reached yet; lower layers are lower still\n    const id = tileId(L, hex.q, hex.r);\n    if (supported(id, now)) return { L, id };\n  }\n  return null;\n}\nfunction reportOut(now) {\n  if (me.out) return;\n  me.out = true;\n  sfx('out');\n  send({ type: 'ghostdrop:out', at: now, y: me.y });\n  if (!LIVE) {\n    drop.out[me.pid] = { at: now };\n    drop.state = 'done';\n    const best = studio.load('best');\n    const lasted = now - drop.startAt;\n    if (!best || lasted > best) studio.save('best', lasted);\n  }\n}\nfunction steer(input, pressA, pressB) {\n  const sx = input.x || 0, sz = input.y || 0, len = Math.hypot(sx, sz);\n  const dirX = len > 0.12 ? sx / len : 0, dirZ = len > 0.12 ? sz / len : 0;\n  if (len > 0.12) me.face = { x: dirX, z: dirZ };\n  if (me.dive <= 0) {\n    const speed = CONFIG.moveSpeed * Math.min(1, len);\n    me.vx = dirX * speed; me.vz = dirZ * speed;\n  }\n  if (pressA && me.ground) { me.vy = CONFIG.jumpSpeed; me.ground = null; me.floatMs = CONFIG.floatMs; }\n  if (pressB && me.diveCool <= 0) {\n    me.dive = CONFIG.diveMs; me.diveCool = CONFIG.diveCooldownMs;\n    me.vx = me.face.x * CONFIG.diveSpeed; me.vz = me.face.z * CONFIG.diveSpeed;\n    me.ground = null; me.vy = 1.2;\n  }\n}\nfunction simulate(dt, now) {\n  me.diveCool = Math.max(0, me.diveCool - dt * 1000);\n  const prevY = me.y;\n  me.x += me.vx * dt; me.z += me.vz * dt;\n  if (me.ground) {\n    const hex = hexAt(me.x, me.z);\n    const id = hex && tileId(me.layer, hex.q, hex.r);\n    if (id && supported(id, now)) { me.ground = id; stepOn(id, now); return; }\n    me.ground = null; me.vy = 0;                        // the floor went: start falling\n    sfx('fall');\n  }\n  let g = CONFIG.gravity;\n  if (me.dive > 0) { me.dive -= dt * 1000; g = 0; }\n  else if (me.holdA && me.floatMs > 0) { g = CONFIG.floatGravity; me.floatMs -= dt * 1000; }\n  me.vy = me.dive > 0 ? -1.2 : Math.max(-CONFIG.fallSpeed, me.vy - g * dt);\n  me.y += me.vy * dt;\n  if (me.vy <= 0) {\n    const landing = findLanding(prevY, me.y, now);\n    if (landing) {\n      me.y = layerY(landing.L); me.layer = landing.L; me.ground = landing.id;\n      me.vy = 0; me.dive = 0;\n      stepOn(landing.id, now);\n      return;\n    }\n  }\n  if (me.y < VOID_Y) {\n    if (drop.state === 'running') reportOut(now);\n    else spawnMe();                                     // a fall before the drop starts: back to your spot\n  }\n}\n\n// ---------- tiles: lit when stepped on, then they vanish for everyone ----------\nlet lastVanishSfx = 0;\nfunction updateTiles(now, dt) {\n  // fade the layers above the camera's focus; they come back when you are on top of them\n  const k = 1 - Math.exp(-dt * 6);\n  for (let L = 0; L < LAYERS; L++) {\n    const want = layerY(L) > camFocus.y + 0.2 ? 0.22 : 1;\n    const next = Math.abs(want - fadeOf[L]) < 0.01 ? want : fadeOf[L] + (want - fadeOf[L]) * k;\n    if (next !== fadeOf[L]) {\n      fadeOf[L] = next;\n      layerRims[L].material.opacity = 0.85 * next;\n      for (const t of tiles.values()) if (t.L === L && !t.gone) tileLook(t, next);\n    }\n  }\n  for (const id in drop.tiles) {\n    const t = tiles.get(id), rec = drop.tiles[id];\n    if (!t) continue;\n    if (now < rec.vanishAt) {\n      // stepped on: it flashes white-pink faster and faster until it goes\n      const left = Math.max(0, (rec.vanishAt - now) / CONFIG.tileDelayMs);\n      const pulse = 0.5 + 0.5 * Math.sin(now / (18 + 40 * left));\n      t.top.color.copy(t.color).lerp(LIT, 0.6);\n      t.top.emissive.copy(LIT);\n      t.top.emissiveIntensity = 0.5 + 0.9 * pulse;\n      t.lit = true;\n    } else {\n      if (!t.gone) {\n        t.gone = true;\n        if (performance.now() - lastVanishSfx > 150) { lastVanishSfx = performance.now(); sfx('vanish'); }\n      }\n      const k = Math.min(1, (now - rec.vanishAt) / 320);\n      t.mesh.scale.set(1 + k * 0.25, Math.max(0.02, 1 - k), 1 + k * 0.25);\n      tileLook(t, (1 - k) * fadeOf[t.L]);\n      t.mesh.visible = k < 1;\n    }\n  }\n}\n\n// ---------- camera: behind and above your ghost, always under the layer above ----------\n// Layers are far enough apart (layerGap) that the camera fits between them: it rides a few metres\n// above your ghost, looks down at it, and never rises into the layer above. On a phone held upright\n// it sits a little further back so the tiles round you stay in view.\nconst camFocus = new THREE.Vector3(0, layerY(0), 0);\nconst camWant = new THREE.Vector3();\nfunction ceilingAbove(y) {                              // the underside of the nearest layer above height y\n  let ceil = Infinity;\n  for (let L = 0; L < LAYERS; L++) if (layerY(L) > y + 0.3) ceil = layerY(L) - TILE_H - 0.9;\n  return ceil;\n}\nfunction updateCamera(dt) {\n  let fx = 0, fy = 0, fz = 0, n = 0;\n  const away = me.out || me.watching;   // out or watching: follow the ghosts still in the drop\n  if (!away) { fx = me.x; fy = me.y; fz = me.z; }\n  else {\n    for (const pid of drop.order) {\n      const a = actors.get(pid);\n      if (!a || drop.out[pid] || pid === me.pid) continue;\n      fx += a.root.position.x; fy += a.root.position.y; fz += a.root.position.z; n++;\n    }\n    if (n) { fx /= n; fy /= n; fz /= n; } else { fy = layerY(Math.min(1, LAYERS - 1)); }\n  }\n  // follow sideways gently, but keep up with a fall\n  const kxz = 1 - Math.exp(-dt * 5), ky = 1 - Math.exp(-dt * 9);\n  camFocus.x += (fx * 0.75 - camFocus.x) * kxz;          // drift only part way, so the arena stays framed\n  camFocus.z += (fz * 0.75 - camFocus.z) * kxz;\n  camFocus.y += (fy - camFocus.y) * ky;\n  const portrait = camera.aspect < 0.8;\n  const back = (away ? 15 : 9.5) * (portrait ? 1.2 : 1), up = (away ? 6.5 : 4.6) * (portrait ? 1.1 : 1);\n  const camY = Math.min(camFocus.y + up, ceilingAbove(camFocus.y));\n  camWant.set(camFocus.x, camY, camFocus.z + back);\n  camera.position.x += (camWant.x - camera.position.x) * kxz;\n  camera.position.z += (camWant.z - camera.position.z) * kxz;\n  camera.position.y += (camWant.y - camera.position.y) * ky;\n  // look at the ghost (a little above its feet), with the ghost itself in the lower middle of the screen\n  const lookX = away ? camFocus.x : fx, lookZ = away ? camFocus.z : fz;\n  camera.lookAt(lookX, camFocus.y + 0.4, lookZ - 1.2);\n}\n\n// ---------- HUD and the panel (title, lobby, winner) ----------\nconst el = (id) => document.getElementById(id);\nconst countEl = el('count'), countLabel = el('countLabel'), layerText = el('layerText'), swatch = el('swatch'), bigEl = el('big'), hintEl = el('hint');\nconst panel = el('panel'), ptitle = el('ptitle'), pbody = el('pbody'), pbtn = el('pbtn'), rosterEl = el('roster');\nlet lastBig = '', panelKey = '', panelAction = null;\n\nfunction panelFor(now) {\n  if (!LIVE) {\n    if (drop.state === 'lobby') return { title: 'Ghost Drop', body: 'Practice drop: you alone on the top layer. Step, jump and dive, and see how long you last.', button: 'Tap to start', action: startPractice };\n    if (me.out && drop.state === 'done') {\n      const best = studio.load('best');\n      return { title: 'You dropped out', body: `You lasted ${((now - drop.startAt) / 1000).toFixed(1)}s.${best ? ` Best: ${(best / 1000).toFixed(1)}s.` : ''}`, button: 'Try again', action: startPractice };\n    }\n    return null;\n  }\n  const n = drop.order.length, need = CONFIG.minPlayers;\n  if (drop.state === 'lobby') {\n    const more = need - n;\n    return { title: 'Ghost Drop', roster: true,\n      body: more > 0 ? `Waiting for ${more} more ${more === 1 ? 'player' : 'players'} to drop in. Up to ${CONFIG.maxPlayers} can play.` : 'Ready when you are. Anyone can start the drop.',\n      button: 'Start the drop', disabled: more > 0, action: () => send({ type: 'ghostdrop:go' }) };\n  }\n  if (drop.state === 'done') {\n    const winner = drop.winner;\n    return { title: winner === me.pid ? 'You won!' : `${winner ? nameOf(winner) : 'Nobody'} wins`,\n      body: winner ? 'Last one standing. Back to the island in a moment.' : 'Everyone fell together. Back to the island in a moment.' };\n  }\n  if (me.out && drop.state === 'running') return { title: 'You dropped out', body: 'Watching the others.', button: 'Back to the island', action: () => send({ type: 'ghostdrop:close' }) };\n  if (me.watching && drop.state === 'running') return { title: 'Watching the drop', body: 'The ghosts are on the layers. Jump in when the next drop opens.', button: 'Back to the island', action: () => send({ type: 'ghostdrop:close' }) };\n  return null;\n}\nfunction renderPanel(now) {\n  const p = panelFor(now);\n  const key = p ? [p.title, p.body, p.button, p.disabled, p.roster ? drop.order.join(',') : ''].join('|') : '';\n  if (key === panelKey) return;\n  panelKey = key;\n  if (!p) { panel.classList.add('hidden'); panelAction = null; return; }\n  panel.classList.remove('hidden');\n  ptitle.textContent = p.title;\n  pbody.textContent = p.body;\n  rosterEl.replaceChildren(...(p.roster ? drop.order.map((pid) => {\n    const s = document.createElement('span');\n    s.textContent = nameOf(pid);\n    s.style.boxShadow = `inset 3px 0 0 ${colorOf(pid)}`;\n    return s;\n  }) : []));\n  pbtn.hidden = !p.button;\n  pbtn.textContent = p.button || '';\n  pbtn.disabled = !!p.disabled;\n  panelAction = p.action || null;\n}\npbtn.addEventListener('click', () => { if (panelAction) panelAction(); });\n\nfunction hud(now) {\n  const inRound = drop.order.length;\n  const waiting = drop.state === 'lobby';\n  countLabel.textContent = waiting ? 'Ghosts in' : 'Players left';\n  countEl.textContent = !inRound ? '-' : waiting ? String(inRound)\n    : String(drop.order.filter((pid) => !drop.out[pid]).length);\n  if (me.out) { layerText.textContent = 'Dropped out'; swatch.style.background = '#77708f'; }\n  else {\n    const colour = CONFIG.layerColors[me.layer % CONFIG.layerColors.length];\n    layerText.textContent = `Layer ${me.layer + 1} of ${LAYERS}`;\n    swatch.style.background = colour; swatch.style.color = colour;\n  }\n  let big = '';\n  if (drop.state === 'countdown') { const k = Math.ceil((drop.startAt - now) / 1000); big = k > 0 ? String(k) : 'GO!'; }\n  else if (drop.state === 'running' && now - drop.startAt < 900) big = 'GO!';\n  if (big !== lastBig) {\n    lastBig = big;\n    bigEl.textContent = big;\n    bigEl.classList.toggle('on', !!big);\n    if (big) sfx(big === 'GO!' ? 'go' : 'tick');\n  }\n  hintEl.textContent = me.watching || me.out ? ''\n    : drop.state === 'running' ? 'Stick to move. Hold A to float. B dives forward.'\n    : 'Stick to move. A jumps. B dives.';\n}\n\n// ---------- Worlds ----------\naddEventListener('message', (event) => {\n  const message = event.data || {};\n  if (message.type === 'ghostdrop:round') applyRound(message);\n});\nlet lastPosSent = 0;\nfunction reportPos(now, ts) {\n  if (!LIVE || me.out || me.watching || ts - lastPosSent < 180) return;\n  lastPosSent = ts;\n  send({ type: 'ghostdrop:pos', x: me.x, y: me.y, z: me.z, r: Math.atan2(me.face.x, me.face.z), layer: me.layer });\n}\n\n// ---------- the loop ----------\nlet prevA = false, prevB = false, last = performance.now();\nfunction tick(now, dt) {\n  if (!LIVE && drop.state === 'countdown' && now >= drop.startAt) drop.state = 'running';\n  const input = studio.input || {};\n  const pressA = !!input.a && !prevA, pressB = !!input.b && !prevB;\n  prevA = !!input.a; prevB = !!input.b;\n  me.holdA = !!input.a;\n  const frozen = me.out || me.watching || drop.state === 'done' || drop.state === 'none' || (drop.state === 'countdown' && now < drop.startAt);\n  if (!frozen) steer(input, pressA, pressB);\n  if (!me.out && !me.watching) simulate(dt, now);\n  updateTiles(now, dt);\n}\nfunction frame(ts) {\n  requestAnimationFrame(frame);\n  const dt = Math.min(0.05, Math.max(0, (ts - last) / 1000));\n  last = ts;\n  const now = serverNow();\n  tick(now, dt);\n  updateActors(dt);\n  updateWisps(dt);\n  updateCamera(dt);\n  for (let i = 0; i < puffs.length; i++) puffs[i].position.x += Math.sin(now / 1500 + i) * dt * 0.6;\n  for (const g of islands) { g.position.y = g.userData.y + Math.sin(ts / 1800 + g.userData.phase) * 0.6; g.rotation.y += dt * 0.02; }\n  hud(now);\n  renderPanel(now);\n  reportPos(now, ts);\n  renderer.render(scene, camera);\n}\n\n// Read-only view of the round for automated playtests (no effect on play).\nwindow.ghostDropState = () => ({\n  live: LIVE, state: drop.state, layer: me.layer, y: +me.y.toFixed(2), out: me.out,\n  tiles: Object.keys(drop.tiles).length, alive: drop.order.filter((pid) => !drop.out[pid]).length,\n});\n\n// ---------- start ----------\nstudio.controls?.({ stick: true, buttons: ['Jump', 'Dive'] });\nawait loadGhosts();\nif (!LIVE) spawnMe();\nrequestAnimationFrame(frame);\nsend({ type: 'ghostdrop:ready' });\n</script>\n</body>\n</html>\n"
